def resolve(path, cwd, links):
    # Start with current working directory as base
    if path.startswith('/'):
        current = '/'
        components = [c for c in path.split('/') if c and c != '.']
    else:
        current = cwd
        components = [c for c in path.split('/') if c and c != '.']

    link_count = 0
    max_links = 8
    i = 0

    while i < len(components):
        component = components[i]

        if component == '..':
            # Move to parent directory
            if current != '/':
                current = current.rsplit('/', 1)[0]
                if not current:
                    current = '/'
        else:
            # Append component to current path
            if current == '/':
                new_path = '/' + component
            else:
                new_path = current + '/' + component

            # Check if this path is a symlink
            if new_path in links:
                link_count += 1
                if link_count > max_links:
                    return None

                # Get the symlink target
                target = links[new_path]

                # Resolve remaining components after we process the link
                remaining = components[i+1:]

                # Parse the target
                if target.startswith('/'):
                    # Absolute symlink target
                    current = '/'
                    target_components = [c for c in target.split('/') if c and c != '.']
                else:
                    # Relative symlink target - relative to the directory containing the link
                    if new_path == '/':
                        current = '/'
                    else:
                        current = new_path.rsplit('/', 1)[0]
                        if not current:
                            current = '/'
                    target_components = [c for c in target.split('/') if c and c != '.']

                # Prepend target components to remaining components
                components = target_components + remaining
                i = 0
            else:
                # Not a symlink, just move to this path
                current = new_path

        i += 1

    # Remove trailing slash if present (except for root)
    if current != '/' and current.endswith('/'):
        current = current.rstrip('/')

    return current

